-- ── OPEX: 77 000 ₽/мес первые шесть месяцев, далее 65 000 ₽ (без дизайнера) ──────────
INSERT INTO `project-fa311fc0-4d87-4781-986.evetis_ref.CT_OPEX` (opex_version, month, cost_item, amount_rub, is_active, source, note, created_at)
SELECT 'OPEX_v1_2026-09', m, item, amt, TRUE, 'OWNER_FACT', note, CURRENT_TIMESTAMP()
FROM UNNEST(GENERATE_DATE_ARRAY(DATE '2026-09-01', DATE '2027-03-01', INTERVAL 1 MONTH)) AS m,
UNNEST([
  STRUCT('FULFILLMENT' AS item, 45000.0 AS amt, 'Фулфилмент Usend' AS note),
  STRUCT('ACCOUNTING', 20000.0, 'Бухгалтерия'),
  STRUCT('DESIGNER', 12000.0, 'Дизайнер — первые шесть месяцев, по март не продлевается')
])
WHERE NOT (item = 'DESIGNER' AND m >= DATE '2027-03-01');

